<?phpnamespace App\Http\Controllers\admin;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\Validator;use Illuminate\Support\Facades\DB;use App\Models\Faq;use App\Models\Blog;class FaqController extends Controller{    public function __construct()    {        $this->middleware('auth');    }                    public function index()    {        $data = Faq::with('blog')->orderBy('created_at','desc')->where('is_delete','0')->paginate(15);        return view('admin.faq.faqlisting',compact('data'));    }    public function addfaq()    {           $blog = Blog::where('is_delete','0')->get();        return view('admin.faq.addfaq',compact('blog'));    }    public function insertfaq(Request $request)    {         $faqData = [];    foreach ($request->title as $key => $title) {        $faqData[] = [            'question' => $title,            'answer' => $request->description[$key]        ];    }    $payload = [        'blog_id' => $request->blog_id,        'title_desc' => json_encode($faqData),     ];    DB::table('faq')->insert($payload);    return redirect('admin/faq')->with('success', 'Your FAQ has been added successfully!');    }    public function editfaq($id){        $blog = Blog::where('is_delete','0')->get();        $data = Faq::where('id',$id)->first();        return view('admin.faq.editfaq',compact('data','blog'));    }        public function deletefaq($id){        $post = Faq::find($id);        $post->is_delete = '1';        $post->update();        return redirect()->back()->with('success', 'Your faq has been Deleted successfully!');    }    public function updatefaq(Request $request)    {        $faqData = [];    foreach ($request->title as $key => $title) {        $faqData[] = [            'question' => $title,            'answer' => $request->description[$key]        ];    }    $payload = [        'blog_id' => $request->blog_id,        'title_desc' => json_encode($faqData),     ];    DB::table('faq')->where('id', $request->id)->update($payload);    return redirect('admin/faq')->with('success', 'Your FAQ has been updated successfully!');    }   }